"""Generated files: index, glossary, feature catalogue, context packs, backlinks. Date-independent: retention lives in retention.py."""
import json
import re

from . import links
from .context import build_context, summary_of

HEADER = "<!-- generated by pb; do not edit -->"
LANGUAGES = {"en": "English", "it": "Italian", "de": "German", "fr": "French", "es": "Spanish"}
CLOSED = {"decision": {"superseded"}, "open-question": {"resolved", "dropped"}, "epic": {"done", "cancelled"}}


def generate(brain):
    written, deleted = [], []

    def write(rel, text):
        path = brain.root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.is_file() or path.read_text(encoding="utf-8") != text:
            path.write_text(text, encoding="utf-8")
        written.append(rel)

    pages = [p for p in brain.pages() if p.type in brain.types]
    write("index.md", _index(brain, pages))
    write("glossary.md", _glossary(brain, pages))
    write("features.md", _features(brain, pages))
    write(".pb/backlinks.json", json.dumps(_backlinks(brain, pages), indent=2, sort_keys=True, ensure_ascii=False) + "\n")

    packs = {f"{p.title}.md": p for p in pages if p.type == "feature"
             or (p.type == "epic" and p.get("status", "active") == "active")}
    for name, p in sorted(packs.items()):
        write(f"context/{name}", build_context(brain, feature=p.title)["markdown"])
    ctx = brain.root / "context"
    for path in sorted(ctx.glob("*.md")) if ctx.is_dir() else []:
        if path.name not in packs:
            path.unlink()
            deleted.append(f"context/{path.name}")
    return {"written": written, "deleted": deleted}


def is_archived(page):
    """Archived pages are flagged by retention (`archived: true`); generation never decides by date."""
    return page.get("archived") is True


def _first_sentence(text, limit=120):
    sentence = re.split(r"(?<=[.!?])\s", text.strip(), maxsplit=1)[0] if text else ""
    return sentence if len(sentence) <= limit else sentence[:limit - 1].rstrip() + "…"


def _heading(folder):
    name = folder.rstrip("/").split("/")[-1].replace("-", " ")
    return name[:1].upper() + name[1:]


def _index(brain, pages):
    product = brain.config.get("product") or "Product"
    out = [HEADER, f"# {product} brain index", "",
           "Also: [glossary](glossary.md) · [feature catalogue by capability](features.md)", ""]
    archived = 0
    order = [("functional", "Functional"), ("technical", "Technical")]
    types_by_area = {}
    for t in sorted(brain.types.values(), key=lambda t: t.folder):
        types_by_area.setdefault(t.area, []).append(t)

    def lines_for(typedef):
        nonlocal archived
        lines = []
        for p in sorted((p for p in pages if p.type == typedef.name), key=lambda p: p.title.lower()):
            if is_archived(p):
                archived += 1
                continue
            line = f"- [[{p.title}]]"
            if p.type in CLOSED and p.get("status"):
                line += f" ({p.get('status')})"
            summary = _first_sentence(summary_of(p))
            lines.append(line + (f" — {summary}" if summary else ""))
        return lines

    for area, title in order:
        out += [f"## {title}", ""]
        for t in types_by_area.pop(area, []):
            out += [f"### {_heading(t.folder)}", ""] + (lines_for(t) or ["_none yet_"]) + [""]
    for area in sorted(types_by_area, key=lambda a: str(a)):
        for t in types_by_area[area]:
            out += [f"## {_heading(t.folder)}", ""] + (lines_for(t) or ["_none yet_"]) + [""]
    if archived:
        out += [f"Archived: {archived} pages (not listed).", ""]
    return "\n".join(out).rstrip() + "\n"


def _cell(text):
    return str(text).replace("|", "\\|").replace("\n", " ")


def _glossary(brain, pages):
    langs = brain.config.get("glossary_languages") or ["en"]
    names = [LANGUAGES.get(l, l) for l in langs]
    out = [HEADER, "# Glossary", "", "| " + " | ".join(names + ["Definition"]) + " |",
           "|" + "---|" * (len(names) + 1)]
    concepts = [p for p in pages if p.type == "concept"]
    for p in sorted(concepts, key=lambda p: str(p.get(f"term_{langs[0]}") or p.title).lower()):
        cells = []
        for i, lang in enumerate(langs):
            term = p.get(f"term_{lang}")
            if i == 0:
                cells.append(f"[[{p.title}\\|{_cell(term or p.title)}]]")
            else:
                cells.append(_cell(term) if term else "—")
        cells.append(_cell(_first_sentence(summary_of(p), 200)))
        out.append("| " + " | ".join(cells) + " |")
    return "\n".join(out) + "\n"


STATUS_ORDER = ["released", "in-progress", "planned", "idea", "deprecated"]
UNCATEGORISED = "Uncategorised"


def _features(brain, pages):
    """Feature catalogue: features grouped by capability, then by status."""
    product = brain.config.get("product") or "Product"
    out = [HEADER, f"# {product} features", ""]
    groups = {}
    for p in (p for p in pages if p.type == "feature"):
        groups.setdefault(str(p.get("capability") or "").strip() or UNCATEGORISED, []).append(p)
    if not groups:
        return "\n".join(out + ["_none yet_"]) + "\n"
    rank = {s: i for i, s in enumerate(STATUS_ORDER)}

    def roles(p):
        return ", ".join(f"[[{t}]]" for t in links.extract(" ".join(str(r) for r in _as_list(p.get("roles")))))

    names = sorted((g for g in groups if g != UNCATEGORISED), key=str.lower)
    for name in names + ([UNCATEGORISED] if UNCATEGORISED in groups else []):
        out += [f"## {name}", "", "| Feature | Status | Roles | Summary |", "|---|---|---|---|"]
        for p in sorted(groups[name], key=lambda p: (rank.get(p.get("status") or "idea", 99), p.title.lower())):
            out.append(f"| [[{p.title}]] | {p.get('status') or 'idea'} | {_cell(roles(p)) or '—'} | "
                       f"{_cell(_first_sentence(summary_of(p), 160))} |")
        out.append("")
    return "\n".join(out).rstrip() + "\n"


def _as_list(value):
    if value is None:
        return []
    return value if isinstance(value, list) else [value]


def _backlinks(brain, pages):
    result = {}
    for p in pages:
        targets = links.extract(p.body) + [t for _, t in links.meta_links(p.meta, brain.types.get(p.type))]
        for target in set(targets):
            found, _ = brain.lookup(target)
            if found is not None and found.title != p.title:
                result.setdefault(found.title, set()).add(p.title)
    return {k: sorted(v) for k, v in result.items()}
